import{_ as i,o as t,c as n,a3 as e}from"./chunks/framework.BvvarXmc.js";const m=JSON.parse('{"title":"Saldo Kartu Pelajar & Riwayat Jajan","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-siswa/dompet-kartu-siswa.md","filePath":"panduan-siswa/dompet-kartu-siswa.md","lastUpdated":null}'),r={name:"panduan-siswa/dompet-kartu-siswa.md"};function o(l,a,s,u,d,p){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="saldo-kartu-pelajar-riwayat-jajan" tabindex="-1">Saldo Kartu Pelajar &amp; Riwayat Jajan <a class="header-anchor" href="#saldo-kartu-pelajar-riwayat-jajan" aria-label="Permalink to &quot;Saldo Kartu Pelajar &amp; Riwayat Jajan&quot;">​</a></h1><p>Kartu Pelajar siswa dapat berfungsi sebagai <strong>Smart Card (Dompet Digital)</strong> untuk bertransaksi di kantin sekolah atau koperasi tanpa membawa uang tunai.</p><hr><h2 id="_1-mengecek-saldo-dompet-digital" tabindex="-1">1. Mengecek Saldo Dompet Digital <a class="header-anchor" href="#_1-mengecek-saldo-dompet-digital" aria-label="Permalink to &quot;1. Mengecek Saldo Dompet Digital&quot;">​</a></h2><ol><li>Masuk ke portal siswa pilih menu <strong>Dompet Digital (Smart Wallet)</strong>.</li><li>Anda akan langsung melihat: <ul><li><strong>Saldo Aktif Saat Ini</strong>: Jumlah uang saku yang tersedia di kartu.</li><li><strong>Status Kartu</strong>: Aktif / Terblokir.</li></ul></li></ol><hr><h2 id="_2-cara-mengisi-saldo-top-up" tabindex="-1">2. Cara Mengisi Saldo (Top-Up) <a class="header-anchor" href="#_2-cara-mengisi-saldo-top-up" aria-label="Permalink to &quot;2. Cara Mengisi Saldo (Top-Up)&quot;">​</a></h2><p>Pengisian saldo kartu dapat dilakukan melalui 2 cara:</p><h3 id="cara-a-top-up-online-via-transfer-bank" tabindex="-1">Cara A: Top-Up Online via Transfer Bank <a class="header-anchor" href="#cara-a-top-up-online-via-transfer-bank" aria-label="Permalink to &quot;Cara A: Top-Up Online via Transfer Bank&quot;">​</a></h3><ol><li>Klik tombol <strong>+ Isi Saldo (Top-Up)</strong> di menu Dompet Digital.</li><li>Pilih nominal pengisian (misal: <code>Rp 50.000</code>, <code>Rp 100.000</code>, atau <code>Rp 200.000</code>).</li><li>Pilih bank Virtual Account.</li><li>Lakukan transfer dari rekening orang tua. Saldo kartu siswa akan langsung bertambah seketika.</li></ol><h3 id="cara-b-top-up-tunai-di-sekolah" tabindex="-1">Cara B: Top-Up Tunai di Sekolah <a class="header-anchor" href="#cara-b-top-up-tunai-di-sekolah" aria-label="Permalink to &quot;Cara B: Top-Up Tunai di Sekolah&quot;">​</a></h3><p>Siswa dapat menyerahkan uang tunai ke loket Koperasi Sekolah / Kasir TU untuk diisikan ke kartu pelajar.</p><hr><h2 id="_3-fitur-kontrol-orang-tua-batas-jajan-harian" tabindex="-1">3. Fitur Kontrol Orang Tua (Batas Jajan Harian) <a class="header-anchor" href="#_3-fitur-kontrol-orang-tua-batas-jajan-harian" aria-label="Permalink to &quot;3. Fitur Kontrol Orang Tua (Batas Jajan Harian)&quot;">​</a></h2><p>Untuk mencegah anak jajan berlebihan:</p><ol><li>Orang tua dapat membuka pengaturan dompet di menu profil anak.</li><li>Atur <strong>Batas Pengeluaran Harian (Daily Limit)</strong>, misalnya maksimal <code>Rp 25.000 / hari</code>.</li><li>Jika transaksi di kantin telah mencapai limit tersebut, mesin kasir otomatis akan menolak transaksi tambahan pada hari itu.</li></ol><div class="tip custom-block"><p class="custom-block-title">Jika Kartu Fisik Hilang</p><p>Segera klik tombol <strong>Bekukan Kartu Sementara</strong> di portal siswa agar saldo aman dan tidak dapat digunakan orang lain sampai kartu pengganti dicetak oleh pihak sekolah.</p></div>',17)])])}const g=i(r,[["render",o]]);export{m as __pageData,g as default};
